can_read_continuum_mzml <- function() {
  file <- system.file('sciex/20171016_POOL_POS_1_105-134.mzML', package = 'msdata')
  if (!nzchar(file)) {
    return(FALSE)
  }
  isTRUE(try({
    x <- mzR::openMSfile(file)
    on.exit(mzR::close(x), add = TRUE)
    inherits(x, 'mzR')
  }, silent = TRUE))
}

